// Aggregate MCP library discoveries from multiple sources
const githubResults = $input.all()[0].json.items || [];
const npmResults = $input.all()[1].json.objects || [];
const pypiResults = $input.all()[2] || {};

const aggregatedLibraries = [];

// Process GitHub results
for (const repo of githubResults) {
  if (repo.name.toLowerCase().includes('mcp') && repo.description) {
    aggregatedLibraries.push({
      source: 'github',
      library_id: repo.full_name,
      name: repo.name,
      description: repo.description,
      repository_url: repo.html_url,
      documentation_url: repo.html_url,
      last_updated: repo.updated_at,
      stars: repo.stargazers_count,
      language: repo.language,
      capabilities: ['repository_access', 'code_analysis', 'version_control']
    });
  }
}

// Process NPM results
for (const pkg of npmResults) {
  if (pkg.package.name.toLowerCase().includes('mcp')) {
    aggregatedLibraries.push({
      source: 'npm',
      library_id: pkg.package.name,
      name: pkg.package.name,
      description: pkg.package.description || 'MCP library package',
      repository_url: pkg.package.links?.repository || '',
      documentation_url: pkg.package.links?.homepage || '',
      last_updated: pkg.package.date,
      version: pkg.package.version,
      capabilities: ['package_management', 'dependency_resolution', 'version_control']
    });
  }
}

// Process PyPI results
if (pypiResults.info) {
  aggregatedLibraries.push({
    source: 'pypi',
    library_id: pypiResults.info.name,
    name: pypiResults.info.name,
    description: pypiResults.info.summary || 'MCP library package',
    repository_url: pypiResults.info.home_page || '',
    documentation_url: pypiResults.info.home_page || '',
    last_updated: pypiResults.info.requires_python,
    version: pypiResults.info.version,
    capabilities: ['python_integration', 'package_management', 'dependency_resolution']
  });
}

// Remove duplicates and sort by relevance
const uniqueLibraries = aggregatedLibraries.filter((lib, index, self) =>
  index === self.findIndex(l => l.library_id === lib.library_id)
);

// Sort by relevance (GitHub stars, update date, etc.)
uniqueLibraries.sort((a, b) => {
  if (a.source === 'github' && b.source !== 'github') return -1;
  if (a.source !== 'github' && b.source === 'github') return 1;
  return (b.stars || 0) - (a.stars || 0);
});

return uniqueLibraries.slice(0, 10); // Return top 10 most relevant

